const hot=(frame,node,dest,tr)=>{ /* fallback hotspot */ const b=node.absoluteBoundingBox,fb=frame.absoluteBoundingBox;const r=figma.createRectangle();r.name='Hotspot · '+node.name;r.resize(b.width,b.height);frame.appendChild(r);r.x=b.x-fb.x;r.y=b.y-fb.y;r.fills=[];r.opacity=1;return r;};
async function link(fname,node,dest,kind){
 if(!node){log.push('MISSING node in '+fname+' → '+dest);return;}
 const d=FR[dest];if(!d){log.push('missing dest '+dest);return;}
 const transition=kind==='sheet'?{type:'MOVE_IN',direction:'BOTTOM',matchLayers:false,easing:{type:'EASE_OUT'},duration:0.3}:{type:'DISSOLVE',easing:{type:'EASE_OUT'},duration:0.2};
 const rx=[{trigger:{type:'ON_CLICK'},actions:[{type:'NODE',destinationId:d.id,navigation:'NAVIGATE',transition,preserveScrollPosition:false}]}];
 try{await node.setReactionsAsync(rx);}catch(e){const h=hot(FR[fname],node,dest);await h.setReactionsAsync(rx);log.push('hotspot '+fname+' '+node.name);}
}
